/** The kitchen sink: every area's sheets in one workbook. */
export const KITCHEN_SINK: CorpusEntry = {
  id: "99-kitchen-sink",
  title: "Kitchen sink",
  covers: "every sheet of every non-heavy corpus file in one workbook, with all defined names and properties",
  workbook: () => {
    const sheets: Sheet[] = [];
    const definedNames: NonNullable<Workbook["definedNames"]> = [];
    const used = new Set<string>();
    for (const entry of CORPUS) {
      if (entry.heavy || entry.id === "04-dates-1904" || entry.id === "17-workbook") continue;
      const wb = entry.workbook();
      const offset = sheets.length;
      for (const s of wb.sheets) {
        if (used.has(s.name.toLowerCase())) continue;
        used.add(s.name.toLowerCase());
        // The active sheet of the merges file is a view setting; the kitchen sink opens on its first sheet.
        sheets.push(s);
      }
      for (const d of wb.definedNames ?? []) definedNames.push({ ...d, ...(d.sheet !== undefined ? { sheet: d.sheet + offset } : {}) });
    }
    return { properties: props("Kitchen sink"), definedNames, sheets };
  },
  checks: [{ where: "Every sheet", look: "Page through every sheet and repeat the checks of the individual files where you like.", expect: "No repair prompt; every sheet looks as in its own file." }],
};

export const ALL: CorpusEntry[] = [...CORPUS, KITCHEN_SINK];
